const LOGIK_UNITS = {"busolt":{"busolt-s04-001":[{"o":[0,213],"en":"This is clear: for the form of the understanding is more important than the content, whereas a logical mistake is the very worst: for one does not merely make it; rather one also makes it a rule for oneself to sin.","p":[[0,16,"this is clear"],[17,30,"for the form"],[31,45,"of the understanding"],[46,59,"is more important"],[60,75,"than the content"],[76,107,"whereas a logical mistake"],[108,128,"is the very worst"],[129,161,"for one does not merely make it"],[162,190,"rather one also makes it for oneself"],[191,200,"a rule"],[201,213,"to sin"]]},{"o":[214,288],"en":"It also has a universal utility when it is presented popularly.","p":[[214,226,"it also has"],[227,252,"a universal utility"],[253,288,"when it is presented popularly"]]},{"o":[289,329],"en":"All cognition is accordingly divided","p":[[289,304,"all cognition"],[305,329,"is accordingly divided"]]}],"busolt-s04-002":[{"o":[0,55],"en":"1.) Into Cognitionem ex datis i.e. cognitio a posteriori.","p":[[0,3,"1.)"],[4,27,"into Cognitionem ex datis"],[28,55,"i.e. cognitio a posteriori"]]}],"busolt-s04-003":[{"o":[0,105],"en":"2.) Into Cognitionem ex principiis i.e. cognitio a priori or knowledge of reason antequam nobis data sunt.","p":[[0,3,"2.)"],[4,32,"into Cognitionem ex principiis"],[33,55,"i.e. cognitio a priori"],[56,79,"or knowledge of reason"],[80,105,"antequam nobis data sunt"]]}],"busolt-s04-004":[{"o":[0,337],"en":"Cognitio ex datis is when an object is given to us, e.g. one that we have from the narration of others, e.g. the motion of the stars; but whoever knows how to state why an eclipse of the sun arose just at that time, proves ex principiis. Cognitio a posteriori is the empirical; cognitio a priori is the speculative rational cognition.","p":[[0,22,"cognitio ex datis is"],[23,54,"when an object is given to us"],[55,67,"e.g. one that we"],[68,85,"from the narration"],[86,93,"of others"],[94,99,"have"],[100,117,"e.g. the motion"],[118,129,"of the stars"],[130,154,"but whoever knows how to state"],[155,182,"why an eclipse of the sun"],[183,210,"arose just at that time"],[211,237,"proves ex principiis"],[238,263,"cognitio a posteriori is"],[264,278,"the empirical"],[279,301,"cognitio a priori is"],[302,337,"the speculative rational cognition"]]},{"o":[338,415],"en":"This we have either 1. from concepts, i.e. philosophical cognition","p":[[338,362,"this we have either"],[363,380,"1. from concepts"],[381,415,"i.e. philosophical cognition"]]}],"busolt-s04-005":[{"o":[0,58],"en":"2. From construction, that is mathematical cognition.","p":[[0,20,"2. from construction"],[21,58,"that is mathematical cognition"]]},{"o":[59,209],"en":"Mathematics and philosophy therefore differ greatly: for philosophy is cognized from concepts, mathematics from the construction of concepts.","p":[[59,89,"mathematics and philosophy"],[90,111,"therefore differ greatly"],[112,132,"for philosophy"],[133,151,"is cognized from concepts"],[152,166,"mathematics"],[167,187,"from the construction"],[188,200,"of concepts"],[201,209,"cognized"]]},{"o":[210,267],"en":"Both, however, are not distinguished according to the object.","p":[[210,231,"both, however, are not"],[232,252,"according to the object"],[253,267,"distinguished"]]},{"o":[268,316],"en":"For philosophy too has magnitudes as its object.","p":[[268,293,"for philosophy too"],[294,304,"has magnitudes"],[305,316,"as its object"]]},{"o":[317,485],"en":"Both are rational cognitions, and indeed both speculative; the difference lies in this, that the one rests on concepts, the other on the construction of concepts.","p":[[317,352,"both are rational cognitions"],[353,379,"and indeed both speculative"],[380,408,"the difference lies in this"],[409,421,"that the one"],[422,436,"on concepts"],[437,447,"the other"],[448,464,"on the construction"],[465,477,"of concepts"],[478,485,"rests"]]},{"o":[486,692],"en":"E.g. if I wanted to reflect on a triangle, how great the angle is that contains all three in itself, I would find out nothing philosophically in order to have a correct concept of it.","p":[[486,499,"e.g. if I"],[500,519,"on a triangle"],[520,534,"wanted to reflect"],[535,565,"how great the angle is"],[566,579,"that all three"],[580,598,"contains in itself"],[599,649,"I would find out nothing philosophically"],[650,676,"in order a correct concept"],[677,692,"to have of it"]]},{"o":[693,790],"en":"I must therefore construct the concepts, i.e. I must see the things in the singular coram intuitu.","p":[[693,705,"I must therefore"],[706,730,"construct the concepts"],[731,743,"i.e. I must"],[744,753,"the things"],[754,766,"in the singular"],[767,780,"coram intuitu"],[781,790,"see"]]},{"o":[791,876],"en":"Intuitus a priori is when I do not think and draw the figure from experience.","p":[[791,812,"intuitus a priori is"],[813,835,"when I the figure"],[836,859,"not from experience"],[860,876,"think and draw"]]},{"o":[877,945],"en":"Intuitus empiricus, however, when I make the figure from experience.","p":[[877,901,"intuitus empiricus, however"],[902,920,"when I the figure"],[921,938,"from experience"],[939,945,"make"]]},{"o":[946,998],"en":"Mathematics has to do with the intuitus a priori.","p":[[946,960,"mathematics"],[961,998,"has to do with the intuitus a priori"]]},{"o":[999,1177],"en":"Otherwise one is accustomed to distinguish philosophy and mathematics according to the object, by saying that philosophy deals with qualities, mathematics with quantities.","p":[[999,1015,"otherwise one is accustomed"],[1016,1046,"philosophy and mathematics"],[1047,1063,"according to the object"],[1064,1081,"to distinguish"],[1082,1104,"by saying"],[1105,1127,"philosophy deals"],[1128,1144,"with qualities"],[1145,1159,"mathematics"],[1160,1177,"with quantities"]]},{"o":[1178,1365],"en":"This difference, however, is incorrect, for philosophy as well as mathematics deal with magnitudes, mathematics however especially, because I can construct a concept only according to magnitude.","p":[[1178,1201,"this difference, however"],[1202,1216,"is incorrect"],[1217,1255,"for philosophy as well as mathematics"],[1256,1274,"deal with magnitudes"],[1275,1305,"mathematics however especially"],[1306,1318,"because I only"],[1319,1333,"according to magnitude"],[1334,1365,"can construct a concept"]]},{"o":[1366,1433],"en":"Philosophy is a science, and must make up a system.","p":[[1366,1403,"philosophy is a science"],[1404,1433,"and must make up a system"]]},{"o":[1434,1502],"en":"It is therefore the system of all speculative cognition from concepts.","p":[[1434,1457,"it is therefore the system"],[1458,1487,"of all speculative cognition"],[1488,1502,"from concepts"]]},{"o":[1503,1594],"en":"Our thinking is properly a cognition through concepts, or a discursive cognition.","p":[[1503,1515,"our thinking"],[1516,1545,"is properly a cognition"],[1546,1561,"through concepts"],[1562,1594,"or a discursive cognition"]]},{"o":[1595,1680],"en":"The senses, however, give us only cognition through intuition, or intuitive cognitions.","p":[[1595,1609,"the senses, however"],[1610,1634,"give us only cognition"],[1635,1652,"through intuition"],[1653,1680,"or intuitive cognitions"]]},{"o":[1681,1819],"en":"For him who has the former one could call a philosopher, but him who has the other a man of healthy understanding.","p":[[1681,1689,"for him"],[1690,1718,"who has the former"],[1719,1748,"one could call a philosopher"],[1749,1757,"but him"],[1758,1777,"who has the other"],[1778,1788,"a man"],[1789,1811,"of healthy understanding"],[1812,1819,"call"]]},{"o":[1820,1901],"en":"Philosophy is not practical, but is the knowledge of the laws of reason.","p":[[1820,1856,"philosophy is not practical"],[1857,1887,"but is the knowledge of the laws"],[1888,1901,"of reason"]]},{"o":[1902,1944],"en":"The laws according to which we proceed are","p":[[1902,1914,"the laws"],[1915,1939,"according to which we proceed"],[1940,1944,"are"]]}],"busolt-s04-006":[{"o":[0,56],"en":"1.) Rules of skill, i.e. political laws.","p":[[0,10,"1.) rules"],[11,31,"of skill"],[32,56,"i.e. political laws"]]}],"busolt-s04-007":[{"o":[0,49],"en":"2.) Rules of wisdom, i.e. moral laws.","p":[[0,10,"2.) rules"],[11,24,"of wisdom"],[25,49,"i.e. moral laws"]]}],"busolt-s04-008":[{"o":[0,134],"en":"In philosophy one must distinguish objective and subjective cognition. Objectively this cognition can be a rational cognition","p":[[0,18,"in philosophy"],[19,39,"one must distinguish"],[40,77,"objective and subjective cognition"],[78,109,"objectively this cognition can be"],[110,134,"a rational cognition"]]}],"busolt-s04-009":[{"o":[0,92],"en":"be, a priori; subjectively philosophy can be nothing but a historical cognition.","p":[[0,15,"be, a priori"],[16,47,"subjectively philosophy can"],[48,92,"be nothing but a historical cognition"]]},{"o":[93,160],"en":"Philosophy therefore cognizes ex conceptu, mathematics ex intuitu.","p":[[93,121,"philosophy therefore cognizes"],[122,133,"ex conceptu"],[134,148,"mathematics"],[149,160,"ex intuitu"]]},{"o":[161,436],"en":"In philosophy an intuitus can only be an example, whereas in mathematics an intuitus is what is essential; hence Wolff errs when in his Auszug of all the mathematical sciences he gives, of similarity, only a thoroughly speculative definition.","p":[[161,179,"in philosophy"],[180,197,"an intuitus can"],[198,220,"only be an example"],[221,232,"whereas"],[233,250,"in mathematics"],[251,263,"an intuitus"],[264,284,"is what is essential"],[285,303,"hence Wolff errs"],[304,311,"when he"],[312,329,"in his Auszug"],[330,364,"of all the mathematical sciences"],[365,384,"of similarity"],[385,436,"gives only a thoroughly speculative definition"]]},{"o":[437,504],"en":"Euclid does quite otherwise, who goes at once to the application.","p":[[437,467,"Euclid does quite otherwise"],[468,480,"who at once"],[481,504,"goes to the application"]]},{"o":[505,585],"en":"Philosophical cognition is accordingly discursive, mathematical intuitive.","p":[[505,534,"philosophical cognition"],[535,557,"is accordingly discursive"],[558,585,"mathematical intuitive"]]},{"o":[586,1123],"en":"Philosophy cannot be learned by heart, and a philosopher can be no adherent of a particular sect; for in that way he will learn philosophy, but not philosophizing; in mathematics, on the other hand, one can follow the utility, the necessity of another theorem, since in mathematics, as an intuitive science, one can convince oneself through the guiding thread of intuition whether this or that one has judged correctly; whereas in philosophy, as a discursive science, this guiding thread is lacking.","p":[[586,601,"philosophy"],[602,638,"cannot be learned by heart"],[639,656,"and a philosopher"],[657,675,"can be no adherent"],[676,703,"of a particular sect"],[704,736,"for in that way he will learn philosophy"],[737,762,"but not philosophizing"],[763,770,"learn"],[771,798,"in mathematics, on the other hand"],[799,819,"one can follow the utility"],[820,838,"the necessity"],[839,862,"of another theorem"],[863,872,"follow"],[873,879,"since one"],[880,897,"in mathematics"],[898,930,"as an intuitive science"],[931,942,"oneself"],[943,962,"through the guiding thread"],[963,977,"of intuition"],[978,994,"can convince"],[995,1015,"whether this or that one"],[1016,1035,"has judged correctly"],[1036,1046,"whereas"],[1047,1065,"in philosophy"],[1066,1099,"as a discursive science"],[1100,1123,"this guiding thread is lacking"]]},{"o":[1124,1230],"en":"When one finds qui dicunt academia, it means the Platonists, qui dicunt Porticus means Stoics.","p":[[1124,1140,"when one finds"],[1141,1161,"qui dicunt academia"],[1162,1192,"it means the Platonists"],[1193,1212,"qui dicunt Porticus"],[1213,1230,"means Stoics"]]},{"o":[1231,1293],"en":"When one finds qui dicunt horti, it means the Epicureans.","p":[[1231,1246,"when one finds"],[1247,1263,"qui dicunt horti"],[1264,1293,"it means the Epicureans"]]}],"busolt-s04-010":[{"o":[0,81],"en":"Philosophy is a speculative rational cognition according to rules in abstracto.","p":[[0,19,"philosophy is"],[20,55,"a speculative rational cognition"],[56,67,"according to rules"],[68,81,"in abstracto"]]},{"o":[82,323],"en":"It must be a system, that is: everything in it must be presented according to a lawful order, for through aesthetics the system is distinguished from the aggregate, in which everything is thrown together, which is also called rhapsody.","p":[[82,106,"it must be a system"],[107,115,"that is"],[116,131,"everything in it must"],[132,163,"according to a lawful order"],[164,183,"be presented"],[184,208,"for through aesthetics"],[209,238,"the system is distinguished"],[239,252,"from the aggregate"],[253,264,"in which everything"],[265,293,"is thrown together"],[294,323,"which is also called rhapsody"]]}],"busolt-s04-011":[{"o":[0,355],"en":"Philosophy is a system of rational cognitions; yet objectively it can be a rational cognition and not subjectively: for even philosophy, which is a rational cognition in the strictest understanding of the term, can be learned from another by hearsay; so in respect of this it is subjectively, accordingly, no rational cognition.","p":[[0,30,"philosophy is a system"],[31,57,"of rational cognitions"],[58,81,"yet objectively it can"],[82,111,"be a rational cognition"],[112,133,"and not subjectively"],[134,162,"for even philosophy"],[163,191,"which a rational cognition"],[192,221,"is in the strictest understanding of the term"],[222,245,"can by hearsay"],[246,279,"be learned from another"],[280,290,"so it is"],[291,310,"in respect of this"],[311,328,"subjectively, accordingly"],[329,355,"no rational cognition"]]},{"o":[356,573],"en":"A philosopher is either a practical one, i.e. one who through concepts is master over his passions, or a theoretical one, who is the lawgiver or rather law-expounder of human reason.","p":[[356,382,"a philosopher is either"],[383,399,"a practical one"],[400,417,"i.e. one"],[418,436,"who through concepts"],[437,475,"is master over his passions"],[476,499,"or a theoretical one"],[500,518,"who is the lawgiver"],[519,546,"or rather law-expounder"],[547,573,"of human reason"]]},{"o":[574,819],"en":"The natural scientist is no philosopher, for he uses reason as much as he can, upon natural objects, whereas the metaphysician lets his reason, as it were, contemplate itself, and therefore rightly bears the name philosopher.","p":[[574,589,"the natural scientist"],[590,609,"is no philosopher"],[610,638,"for he uses reason"],[639,655,"as much as he can"],[656,689,"upon natural objects"],[690,717,"whereas the metaphysician"],[718,732,"his reason"],[733,771,"lets, as it were, contemplate itself"],[772,801,"and therefore the name philosopher"],[802,819,"rightly bears"]]},{"o":[820,903],"en":"He is a legislator of humanity, a sophist on the other hand a leguleius of it.","p":[[820,841,"he is a legislator"],[842,857,"of humanity"],[858,878,"a sophist on the other hand"],[879,903,"a leguleius of it"]]}],"busolt-s05-001":[{"o":[0,48],"en":"Here cognition in general is spoken of.","p":[[0,9,"here is"],[10,39,"cognition in general"],[40,48,"spoken of"]]},{"o":[49,244],"en":"Logic itself deals with representations, but not with those of which we are not conscious, i.e. obscure ones, but with clear ones, i.e. with those of which we have a consciousness.","p":[[49,65,"logic itself"],[66,96,"deals with representations"],[97,120,"but not with those"],[121,153,"of which we are not conscious"],[154,171,"i.e. obscure ones"],[172,191,"but with clear ones"],[192,208,"i.e. with those"],[209,244,"of which we have a consciousness"]]},{"o":[245,342],"en":"Every cognition has an object and can therefore be considered in a twofold way: namely","p":[[245,260,"every cognition"],[261,281,"has an object"],[282,296,"and can therefore"],[297,315,"in a twofold way"],[316,334,"be considered"],[335,342,"namely"]]}],"busolt-s05-002":[{"o":[0,59],"en":"1.) In relation to the object, that is the material.","p":[[0,17,"1.) in relation"],[18,36,"to the object"],[37,59,"that is the material"]]}],"busolt-s05-003":[{"o":[0,75],"en":"2.) In relation to the form of the understanding, i.e. the formal of cognition.","p":[[0,17,"2.) in relation"],[18,42,"to the form of the understanding"],[43,59,"i.e. the formal"],[60,75,"of cognition"]]}],"busolt-s05-004":[{"o":[0,108],"en":"In logic one abstracts from the object, and looks to the form of the understanding, i.e. modus cognoscendi.","p":[[0,12,"in logic"],[13,27,"one abstracts"],[28,44,"from the object"],[45,55,"and looks"],[56,68,"to the form"],[69,84,"of the understanding"],[85,108,"i.e. modus cognoscendi"]]},{"o":[109,154],"en":"This formal of cognition is now again:","p":[[109,123,"this formal"],[124,138,"of cognition"],[139,154,"is now again"]]}],"busolt-s05-005":[{"o":[0,35],"en":"1. Logicum, thinking, intellectual","p":[[0,10,"1. Logicum"],[11,21,"thinking"],[22,35,"intellectual"]]}],"busolt-s05-006":[{"o":[0,37],"en":"2. Aestheticum, intuiting, sensual","p":[[0,14,"2. Aestheticum"],[15,28,"intuiting"],[29,37,"sensual"]]}],"busolt-s05-007":[{"o":[0,23],"en":"Representations are:","p":[[0,17,"representations"],[18,23,"are"]]}],"busolt-s05-008":[{"o":[0,79],"en":"1. Subjective, i.e. sensation; it is the alteration of the state in the subject.","p":[[0,13,"1. subjective"],[14,29,"i.e. sensation"],[30,53,"it is the alteration"],[54,67,"of the state"],[68,79,"in the subject"]]}],"busolt-s05-009":[{"o":[0,80],"en":"2. Objective, i.e. cognition; it reflects the representation onto the object.","p":[[0,12,"2. objective"],[13,29,"i.e. cognition"],[30,60,"it reflects the representation"],[61,80,"onto the object"]]}],"busolt-s05-010":[{"o":[0,248],"en":"Sensation can be communicated only to him who has or has had it, hence nothing regular can be established about it either in logic or in aesthetics, because a subject always remains distinct from others, and so too sensation.","p":[[0,10,"sensation"],[11,38,"can be communicated only to him"],[39,67,"who has or has had it"],[68,92,"hence about it can"],[93,111,"either in logic"],[112,133,"or in aesthetics"],[134,162,"nothing regular be established"],[163,179,"because a subject"],[180,196,"always from others"],[197,218,"remains distinct"],[219,248,"and so too sensation"]]},{"o":[249,341],"en":"Every representation is always cognition as intuition: in such a way the representations are","p":[[249,265,"every representation"],[266,286,"is always cognition"],[287,302,"as intuition"],[303,318,"in such a way"],[319,341,"the representations are"]]}],"busolt-s05-011":[{"o":[0,33],"en":"1.) of intuition (sensibility)","p":[[0,18,"1.) of intuition"],[19,33,"(sensibility)"]]}],"busolt-s05-012":[{"o":[0,27],"en":"2.) of concepts (understanding)","p":[[0,16,"2.) of concepts"],[17,27,"(understanding)"]]}],"busolt-s05-013":[{"o":[0,100],"en":"1.) Intuition goes to an individual object, insofar as it is distinguished from others,","p":[[0,18,"1.) intuition"],[19,55,"goes to an individual object"],[56,69,"insofar as it"],[70,80,"from others"],[81,100,"is distinguished"]]}],"busolt-s05-014":[{"o":[0,86],"en":"2.) Concepts go to something universal, for they make the particular universal.","p":[[0,16,"2.) concepts"],[17,45,"go to something universal"],[46,61,"for they make"],[62,86,"the particular universal"]]},{"o":[87,128],"en":"From such divisions there arise then;","p":[[87,112,"from such divisions"],[113,128,"there arise then"]]}],"busolt-s05-015":[{"o":[0,122],"en":"a) Aesthetics, i.e. that discipline which sets forth the rule of perfection from the representations of intuiting.","p":[[0,17,"a) aesthetics"],[18,42,"i.e. that discipline"],[43,56,"which the rule"],[57,75,"of perfection"],[76,97,"from the representations"],[98,112,"of intuiting"],[113,122,"sets forth"]]}],"busolt-s05-016":[{"o":[0,119],"en":"b) Logic is that science which sets forth the rules of perfection from the representations of the understanding.","p":[[0,16,"b) logic is"],[17,38,"that science"],[39,53,"which the rules"],[54,72,"of perfection"],[73,94,"from the representations"],[95,109,"of the understanding"],[110,119,"sets forth"]]}],"busolt-s05-017":[{"o":[0,178],"en":"Logic accordingly has to do with clear representations, i.e. with such concepts of which we are conscious, and these we again divide into distinct and indistinct ones.","p":[[0,9,"logic"],[10,24,"accordingly has"],[25,57,"to do with clear representations"],[58,84,"i.e. with such concepts"],[85,111,"of which we are conscious"],[112,143,"and these we again divide"],[144,161,"into distinct"],[162,178,"and indistinct ones"]]}],"busolt-s05-018":[{"o":[0,154],"en":"A distinct concept is that according to which we cognize the manifold that a thing contains, e.g. in the concept of virtue I think three things","p":[[0,22,"a distinct concept"],[23,37,"is that"],[38,54,"according to which we"],[55,73,"the manifold"],[74,96,"that a thing contains"],[97,105,"cognize"],[106,123,"e.g. in the concept"],[124,134,"of virtue"],[135,154,"I think three things"]]}],"busolt-s05-019":[{"o":[0,23],"en":"1.) Regularity.","p":[[0,23,"1.) regularity"]]}],"busolt-s05-020":[{"o":[0,28],"en":"2.) Freedom to act.","p":[[0,16,"2.) freedom"],[17,28,"to act"]]}],"busolt-s05-021":[{"o":[0,54],"en":"3.) Mastery over the desires and passions.","p":[[0,20,"3.) mastery"],[21,54,"over the desires and passions"]]}],"busolt-s05-022":[{"o":[0,238],"en":"If one has merely a concept of the whole but not of the parts, then the concept is called indeed a clear one, but indistinct; one does not rightly call it confused; for confusedness is opposed to order, but not to distinctness.","p":[[0,12,"if one has merely"],[13,23,"of the whole"],[24,37,"a concept"],[38,65,"but not of the parts"],[66,91,"then the concept is called indeed"],[92,103,"a clear one"],[104,122,"but indistinct"],[123,159,"one does not rightly call it confused"],[160,182,"for confusedness"],[183,209,"is opposed to order"],[210,238,"but not to distinctness"]]},{"o":[239,340],"en":"All cognitions one attains through order, i.e. per reductionem idearum subactis quosdam titulos.","p":[[239,255,"all cognitions"],[256,267,"one attains"],[268,285,"through order"],[286,340,"i.e. per reductionem idearum subactis quosdam titulos"]]},{"o":[341,419],"en":"Between distinct and confused there is still an intermediate thing, namely simple.","p":[[341,372,"between distinct and confused"],[373,401,"there is still an intermediate thing"],[402,419,"namely simple"]]},{"o":[420,508],"en":"A simple representation is that in which no manifoldness is contained.","p":[[420,445,"a simple representation"],[446,459,"is that"],[460,493,"in which no manifoldness"],[494,508,"is contained"]]},{"o":[509,586],"en":"E.g. of a single book I cannot say that it lies in disorder.","p":[[509,537,"e.g. of a single book"],[538,559,"I cannot say"],[560,586,"that it lies in disorder"]]},{"o":[587,668],"en":"The distinctness of intuition does not take place without concepts of the parts.","p":[[587,603,"the distinctness"],[604,618,"of intuition"],[619,637,"does not take place"],[638,651,"without concepts"],[652,668,"of the parts"]]},{"o":[669,793],"en":"– – The distinctness of concepts is not possible otherwise than that one at the same time cognizes and distinguishes the manifold.","p":[[669,689,"– – the distinctness"],[690,702,"of concepts"],[703,728,"is not possible otherwise"],[729,749,"than that one at the same time"],[750,767,"the manifold"],[768,793,"cognizes and distinguishes"]]},{"o":[794,950],"en":"Philosophy is concerned with halting our understanding, in order to resolve our general concepts and to show us the whole store of our cognition.","p":[[794,824,"philosophy is concerned with"],[825,852,"halting our understanding"],[853,893,"in order to resolve our general concepts"],[894,920,"and us the whole store"],[921,939,"of our cognition"],[940,950,"to show"]]},{"o":[951,1049],"en":"Est enim vt aiebat Socrates; Philosophia cognitionem nostrarum, quasi quaedam obstetrix non mater.","p":[[951,979,"Est enim vt aiebat Socrates"],[980,1014,"Philosophia cognitionem nostrarum"],[1015,1049,"quasi quaedam obstetrix non mater"]]}],"busolt-s05-023":[{"o":[0,146],"en":"Thus we learn in philosophy the difference between pride, haughtiness, arrogance, although we already beforehand obtain some concepts of these.","p":[[0,13,"thus we learn"],[14,32,"in philosophy"],[33,48,"the difference"],[49,84,"between pride, haughtiness, arrogance"],[85,109,"although we already beforehand"],[110,120,"of these"],[121,146,"obtain some concepts"]]},{"o":[147,307],"en":"But in philosophy clear concepts are made out of obscure ones, distinct out of clear ones, and a consciousness of our cognition is, as it were, imparted to us in it.","p":[[147,172,"but in philosophy"],[173,206,"clear concepts are made out of obscure ones"],[207,228,"distinct out of clear ones"],[229,260,"and is, as it were, to us in it"],[261,275,"a consciousness"],[276,294,"of our cognition"],[295,307,"imparted"]]},{"o":[308,384],"en":"The difference between logical and aesthetic representations consists in this,","p":[[308,323,"the difference"],[324,369,"between logical and aesthetic representations"],[370,384,"consists in this"]]}],"busolt-s05-024":[{"o":[0,201],"en":"1.) The aesthetic representation is the representation through the senses or the imagination; this imagination belongs, as it were, with the senses, it is their copyist, it is the source of intuition.","p":[[0,32,"1.) the aesthetic representation"],[33,52,"is the representation"],[53,91,"through the senses or the imagination"],[92,109,"this imagination"],[110,146,"belongs, as it were, with the senses"],[147,166,"it is their copyist"],[167,185,"it is the source"],[186,201,"of intuition"]]}],"busolt-s05-025":[{"o":[0,121],"en":"2.) The logical representation is the representation through the understanding, and to think therefore means to cognize through concepts.","p":[[0,28,"2.) the logical representation"],[29,48,"is the representation"],[49,68,"through the understanding"],[69,92,"and to think therefore means"],[93,121,"to cognize through concepts"]]}],"busolt-s05-026":[{"o":[0,166],"en":"The first kind of representation is also called the sensible cognitive faculty, or the lower power of the soul, whereas the second kind is the upper power of the soul.","p":[[0,13,"the first kind"],[14,29,"of representation"],[30,73,"is also called the sensible cognitive faculty"],[74,95,"or the lower power"],[96,105,"of the soul"],[106,113,"called"],[114,139,"whereas the second kind"],[140,155,"the upper power"],[156,166,"of the soul"]]}],"busolt-s05-027":[{"o":[0,186],"en":"Reason stands in relation to the understanding as the understanding does to the senses; both kinds are necessary for a concept, and otherwise no concept can be produced.","p":[[0,16,"reason stands"],[17,49,"in relation to the understanding"],[50,73,"as to the senses"],[74,91,"the understanding does"],[92,103,"both kinds"],[104,134,"are necessary for a concept"],[135,145,"and otherwise"],[146,186,"no concept can be produced"]]},{"o":[187,469],"en":"The aesthetic perfections are either essential, i.e. the conformity of the sensible with the logical, or intellectual: a piece cannot please with the wittiest ideas if one cannot find the agreement of the whole imagining with the theme.","p":[[187,220,"the aesthetic perfections"],[221,247,"are either essential"],[248,269,"i.e. the conformity"],[270,284,"of the sensible"],[285,303,"with the logical"],[304,324,"or intellectual"],[325,339,"a piece can"],[340,368,"with the wittiest ideas"],[369,384,"not please"],[385,399,"if one not"],[400,420,"the agreement"],[421,442,"of the whole imagining"],[443,456,"with the theme"],[457,469,"can find"]]},{"o":[470,776],"en":"From just this essential perfection arises the Sensus publicus, the universal taste: for this is the faculty of choice according to the general laws of sensibility, or the aesthetic perfections are also contingent ones. These one cannot determine, for they go to the subject.","p":[[470,513,"from just this essential perfection"],[514,543,"arises the Sensus publicus"],[544,569,"the universal taste"],[570,598,"for this is the faculty"],[599,607,"of choice"],[608,637,"according to the general laws"],[638,655,"of sensibility"],[656,695,"or the aesthetic perfections"],[696,715,"are also contingent ones"],[716,747,"these one cannot determine"],[748,776,"for they go to the subject"]]}],"busolt-s05-028":[{"o":[0,51],"en":"The general and particular laws of aesthetics.","p":[[0,36,"the general and particular laws"],[37,51,"of aesthetics"]]}],"busolt-s05-029":[{"o":[0,64],"en":"The general laws are possible with regard to intuition.","p":[[0,22,"the general laws"],[23,40,"are with regard"],[41,55,"to intuition"],[56,64,"possible"]]},{"o":[65,239],"en":"For in the judging of the beautiful, which is investigated in aesthetics (whereas in logic the true), intuition is the principal, sensation the accessorium.","p":[[65,86,"for in the judging"],[87,99,"of the beautiful"],[100,124,"which in aesthetics"],[125,140,"is investigated"],[141,177,"(whereas in logic the true)"],[178,211,"intuition is the principal"],[212,239,"sensation the accessorium"]]},{"o":[240,378],"en":"Intuition cannot be shared; but sensations cannot be imparted; if it happens, it happens through likenesses.","p":[[240,254,"intuition"],[255,281,"cannot be shared"],[282,301,"but sensations"],[302,334,"cannot be imparted"],[335,346,"if it happens"],[347,378,"it happens through likenesses"]]},{"o":[379,454],"en":"The private laws rest on the different sensations of each.","p":[[379,398,"the private laws"],[399,441,"rest on the different sensations"],[442,454,"of each"]]},{"o":[455,585],"en":"Sensations are certain alterations of our state through which all our cognitive powers are enlivened and exerted.","p":[[455,476,"sensations are"],[477,497,"certain alterations"],[498,516,"of our state"],[517,554,"through which all our cognitive powers"],[555,585,"are enlivened and exerted"]]},{"o":[586,694],"en":"Taste is the faculty of the sensible power of judging according to general laws of sensibility.","p":[[586,616,"taste is the faculty"],[617,650,"of the sensible power of judging"],[651,676,"according to general laws"],[677,694,"of sensibility"]]},{"o":[695,776],"en":"Feeling is the faculty of sensation according to private laws of sensibility.","p":[[695,722,"feeling is the faculty"],[723,737,"of sensation"],[738,758,"according to private laws"],[759,776,"of sensibility"]]}],"busolt-s05-030":[{"o":[0,82],"en":"From this arises the mixture of our cognitions out of sensations and concepts.","p":[[0,30,"from this arises the mixture"],[31,50,"of our cognitions"],[51,82,"out of sensations and concepts"]]},{"o":[83,157],"en":"If our cognition is separated from all sensations, then it is pure.","p":[[83,104,"if our cognition is"],[105,140,"separated from all sensations"],[141,157,"then it is pure"]]},{"o":[158,216],"en":"The purer the cognition, the less it is sensation.","p":[[158,183,"the purer the cognition"],[184,216,"the less it is sensation"]]},{"o":[217,297],"en":"The stronger the sensation, the less, and correctly, pure is the cognition.","p":[[217,247,"the stronger the sensation"],[248,277,"the less, and correctly, pure"],[278,297,"is the cognition"]]},{"o":[298,507],"en":"Accordingly we must not let ourselves be swept away by the dazzling magic power of the senses, but first ground the cognition itself, and then build the sensation upon it, and so the proper edification arises.","p":[[298,325,"accordingly we must not let ourselves"],[326,358,"by the dazzling magic power"],[359,369,"of the senses"],[370,386,"be swept away"],[387,430,"but first ground the cognition itself"],[431,454,"and then the sensation"],[455,468,"build upon it"],[469,507,"and so the proper edification arises"]]},{"o":[508,624],"en":"Sensations take one by surprise, cognition comes gradually; those are something transitory, this something lasting.","p":[[508,534,"sensations take one by surprise"],[535,566,"cognition comes gradually"],[567,599,"those are something transitory"],[600,624,"this something lasting"]]},{"o":[625,693],"en":"The general aesthetic perfection consists in charm and emotion.","p":[[625,664,"the general aesthetic perfection"],[665,693,"consists in charm and emotion"]]},{"o":[694,730],"en":"(Delinementum est mentis concussio.)","p":[[694,730,"(Delinementum est mentis concussio.)"]]},{"o":[731,804],"en":"Attrahit delinementum, nos quoad contemplandum longius objectum detinent.","p":[[731,753,"Attrahit delinementum"],[754,804,"nos quoad contemplandum longius objectum detinent"]]},{"o":[805,873],"en":"Convolvit concussio animum nobisque quasi quendam horrorem infundit.","p":[[805,831,"Convolvit concussio animum"],[832,873,"nobisque quasi quendam horrorem infundit"]]},{"o":[874,961],"en":"Mens delinementa sentit, quandam animae voluptatem, atque in objectum quasi acquiescit.","p":[[874,898,"Mens delinementa sentit"],[899,925,"quandam animae voluptatem"],[926,961,"atque in objectum quasi acquiescit"]]},{"o":[962,1004],"en":"Concussio est tamquam animae aliqua actio.","p":[[962,1004,"Concussio est tamquam animae aliqua actio"]]},{"o":[1005,1215],"en":"Delinemento, ne ob dulce animis condimentum fastidium moveat, concussionis atque commutationis aliquid admisceatur, conquassatio haec est, habitur quidam dolor, puncto temporis inquinatam voluptatem resolvitur.","p":[[1005,1017,"Delinemento"],[1018,1066,"ne ob dulce animis condimentum fastidium moveat"],[1067,1120,"concussionis atque commutationis aliquid admisceatur"],[1121,1143,"conquassatio haec est"],[1144,1165,"habitur quidam dolor"],[1166,1215,"puncto temporis inquinatam voluptatem resolvitur"]]}]},"blomberg":{}};
